INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.68.0',
  '2026-08-04',
  'Тема запоминает фон, превью с картинкой, галерея из своих фонов + фикс удаления темы',
  E'Своя тема теперь запоминает и фон: при сохранении картинка копируется, поэтому удаление её из своей коллекции тему не ломает. Включаете тему — возвращаются и цвета, и картинка вместе с размещением, размытием и затемнением. На карточке темы эта картинка видна.\n\nВ Админке общую галерею можно пополнять из личной коллекции: кнопка «📥 Из моих фонов» копирует файл в галерею, свой фон остаётся на месте.\n\nИсправлено: не удалялась своя тема. Заодно перестали молча отменяться другие подтверждения удаления.',
  E'Фикс подтверждений (он же причина «не удаляется тема»): window.confirm в вебвью Telegram не показывается и сразу возвращает false. Добавлен confirmAction() в shared/telegram.ts — зовёт WebApp.showConfirm, но ТОЛЬКО если клиент поддерживает Bot API 6.2 (isVersionAtLeast): в старых версиях метод существует, ничего не делает и колбэк не приходит, из-за чего действие зависало навсегда; плюс try/catch с падением обратно на window.confirm. Все confirm( в новых страницах (темы, фоны, галерея, Тесты, Finance) переведены на него.\n\nФон в теме: при сохранении сервер снимает текущий фон и КОПИРУЕТ файл (theme_<rand> в каталоге фонов, вместе с превью), сохраняя в user_themes.bg вид, позицию, размытие, затемнение, масштаб, смещение и точку фокуса. Копия нужна, чтобы тема пережила удаление исходной картинки; при удалении темы её файлы убираются. Включение — POST /appearance/themes/{id}/apply: ставит состояние оформления, фон (bg_kind/bg_value) и размещение одним запросом, клиент затем перечитывает фон. Карточка темы показывает картинку подложкой (используется превью).\n\nГалерея из своих фонов: POST /admin/gallery/images/from-background {image_id, category_id} копирует файл и превью из каталога фонов в каталог галереи и заводит запись; исходная картинка пользователя не трогается. В Админке — кнопка у корня и у каждой категории, выбор в модалке (через Teleport, иначе backdrop-filter карточек ломает position: fixed).\n\nПроверено: тема сохраняет фон → исходная картинка удалена → применение темы возвращает картинку (contain, размытие 4, затемнение -20, фокус 30/70); удаление темы убирает её файлы; копирование в галерею не трогает свой фон; в браузере — превью на карточке, применение темы вместе с фоном, удаление темы.'
);
-- +goose StatementEnd

